using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using Milieu.Assets;
using Milieu.Imaging;
using Milieu.Lighting;
using Milieu.Tests.Support;
using Xunit;

namespace Milieu.Tests;

/// <summary>
/// The bundled scenes' light rigs built into the plugin (docs/adr/0010). The table is generated by
/// `PrepareBackdrops rigs Milieu/DefaultBackdrops Milieu/Assets/BundledLightRigs.Data.cs`; these tests guard its drift.
/// </summary>
public class BundledLightRigsTests
{
    private const string Regenerate =
        "Regenerate the table: dotnet run --project tools/PrepareBackdrops -c Release -- rigs Milieu/DefaultBackdrops Milieu/Assets/BundledLightRigs.Data.cs";

    private static BundledRigEntry Entry(string stem) => BundledLightRigs.All.Single(e => e.Stem == stem);

    [Fact] // [AC-ldr-light-estimate-2]
    public void EveryPinHasValidCurrentRig()
    {
        Assert.Equal(BackdropPins.All.Select(p => p.Stem).Order(), BundledLightRigs.All.Select(e => e.Stem).Order());
        foreach (var pin in BackdropPins.All)
        {
            Assert.True(Entry(pin.Stem).PinSha256 == pin.Sha256, $"{pin.Stem}: the entry is for another .atex pin. {Regenerate}");
            var rig = BundledLightRigs.Find(pin.Stem);
            Assert.True(rig != null, $"{pin.Stem}: no valid current-version estimated rig. {Regenerate}");
            Assert.True(rig!.IsEstimated);
            Assert.Equal(LightRig.RegionCount, rig.Regions.Length);
        }
    }

    [Fact] // [AC-ldr-light-estimate-2] [EDGE-ldr-light-estimate-35]
    public void CommittedJpegsMatchEntryHashes()
    {
        foreach (var pin in BackdropPins.All)
        {
            using var fs = File.OpenRead(Path.Combine(RepoPaths.DefaultBackdrops(), pin.Stem + ".jpeg"));
            var sha = Convert.ToHexString(SHA256.HashData(fs)).ToLowerInvariant();
            Assert.True(sha == Entry(pin.Stem).JpegSha256, $"{pin.Stem}.jpeg changed since its light rig was estimated. {Regenerate}");
        }
    }

    [Fact] // [AC-ldr-light-estimate-2]
    public void MoonHasKey()
    {
        // Planned as SunsetAndMoonHaveKey. Coordinator decision (revision 6, option a): the committed sunset.jpeg's sun
        // core was softened by its preparation (R ≥ 250 but G 240-249, B 100-180), so the clip rule finds no key and
        // bundled Sunset is fills-only, a documented known limit (docs/adr/0010). The moon scene's key must stay.
        var moon = BundledLightRigs.Find("moon");
        Assert.NotNull(moon?.Key);
        var sunset = BundledLightRigs.Find("sunset");
        Assert.NotNull(sunset);
        Assert.Null(sunset!.Key);   // the known limit, pinned so a change is noticed
    }

    [Fact] // [AC-ldr-light-estimate-2] [EDGE-ldr-light-estimate-10]
    public void Find_HandWritten()
    {
        var rig = new LightRig(LightExtractor.Version, new RigLight(0.5f, 0.3f, System.Numerics.Vector3.One),
            Enumerable.Repeat(new RigLight(0.5f, 0.5f, System.Numerics.Vector3.One), 4).ToArray(), System.Numerics.Vector3.One * 4,
            [new RigLight(0.4f, 0.4f, System.Numerics.Vector3.One * 0.5f)], LdrLightEstimator.Version);
        var json = LightRigStore.Serialise(rig);
        var pin = new BackdropPin("moon", "Moon", 1, "aa");
        BackdropPin? Pins(string stem) => stem.Equals("moon", StringComparison.OrdinalIgnoreCase) ? pin : null;
        BundledRigEntry[] Entries(string pinSha, string text) => [new("moon", "jj", pinSha, text)];

        var found = BundledLightRigs.Find("moon", Entries("aa", json), Pins);
        Assert.NotNull(found);
        Assert.Equal(json, LightRigStore.Serialise(found!));
        Assert.NotNull(BundledLightRigs.Find("MOON", Entries("aa", json), Pins));                     // stems ignore case
        Assert.Null(BundledLightRigs.Find("lodge", Entries("aa", json), Pins));                       // no entry (and no pin)
        Assert.Null(BundledLightRigs.Find("moon", [], Pins));                                         // missing entry
        Assert.Null(BundledLightRigs.Find("moon", Entries("bb", json), Pins));                        // stale: the pin changed
        Assert.Null(BundledLightRigs.Find("moon", Entries("aa", json), _ => null));                   // no pin
        Assert.Null(BundledLightRigs.Find("moon", Entries("aa", "{not json"), Pins));                 // invalid
        Assert.Null(BundledLightRigs.Find("moon", Entries("aa", json.Replace($"\"estimated\":{LdrLightEstimator.Version}",
                                                                              $"\"estimated\":{LdrLightEstimator.Version + 1}")), Pins));   // wrong version
        Assert.Null(BundledLightRigs.Find("moon", Entries("aa", LightRigStore.Serialise(rig with { EstimatorVersion = 0, Lamps = [] })), Pins));   // an HDR rig
    }

    [Fact] // [AC-ldr-light-estimate-2]
    [Trait("Speed", "Slow")]
    public void RegeneratedFromCommittedJpegs_MatchesTable()
    {
        foreach (var pin in BackdropPins.All)
        {
            var path = Path.Combine(RepoPaths.DefaultBackdrops(), pin.Stem + ".jpeg");
            var img = ImageLoader.Load(path, ImageKind.Jpeg, default);
            var rig = LdrLightEstimator.Analyse(RadianceProbe.BuildSrgb8(img.Rgb!, img.Width, img.Height)).Rig;
            LightingGoldenTests.AssertJsonClose(Entry(pin.Stem).Json, LightRigStore.Serialise(rig),
                $"{pin.Stem}: re-estimating the committed JPEG doesn't match the table. {Regenerate}");
        }
    }
}
